mapper.select:
select max(version)
from t_r_data_perm_user_effective_snapshot
where user_id = #{userId}

select max(version)
from t_r_data_perm_user_effective_snapshot
where user_id = #{userId}
  and snapshot_time <= #{asOf}

select 
from t_r_data_perm_user_effective_snapshot
where user_id = #{userId}
  and version = #{version}

select s.user_id as userId, u.username as username, s.version as version, s.snapshot_time as snapshotTime, s.scope_code as scopeCode, sc.name as scopeName, s.catalog_name as catalogName, s.database_name as databaseName, s.table_name as tableName, s.column_name as columnName, s.accesses as accesses, s.source_kinds as sourceKinds from t_r_data_perm_user_effective_snapshot s inner join ( select s2.user_id, max(s2.version) as lv from t_r_data_perm_user_effective_snapshot s2
inner join t_r_workspace_member wm2 on wm2.user_id = s2.user_id and wm2.workspace_id = #{workspaceId}
where s2.snapshot_time <= #{asOf}
group by s2.user_id ) lv on lv.user_id = s.user_id and lv.lv = s.version left join t_r_user u on u.id = s.user_id left join t_r_data_perm_scope sc on sc.code = s.scope_code
s.scope_code is not null
and s.user_id in #{uid}
and s.scope_code in #{sc}
and (u.username like concat('%', #{keyword}, '%') or s.catalog_name like concat('%', #{keyword}, '%') or s.database_name like concat('%', #{keyword}, '%') or s.table_name like concat('%', #{keyword}, '%') or s.column_name like concat('%', #{keyword}, '%'))
order by u.username, s.scope_code, s.database_name, s.table_name, s.column_name
